SELECT q.id AS question_id, q.stem AS stem, q.type AS type, n.node_code AS node_code, n.name AS node_name, COUNT(*) AS attempts, SUM(ar.is_correct = 0) AS wrong_count FROM student_course sc JOIN answer_record ar ON ar.student_id = sc.student_id AND ar.course_id = sc.course_id JOIN question q ON q.id = ar.question_id AND q.course_id = sc.course_id AND q.type IN (1, 2, 3) LEFT JOIN ( SELECT question_id, MIN(node_id) AS node_id FROM question_node WHERE weight = 1 GROUP BY question_id ) qn ON qn.question_id = q.id LEFT JOIN kg_node n ON n.id = qn.node_id AND n.archived_at IS NULL WHERE sc.course_id = #{courseId}
AND ar.answered_at >= #{since} AND ar.is_correct IS NOT NULL
AND n.node_code = #{nodeCode}
GROUP BY q.id, n.node_code, n.name HAVING COUNT(*) >= #{minSample} AND SUM(ar.is_correct = 0) > 0 ORDER BY SUM(ar.is_correct = 0) / COUNT(*) DESC, COUNT(*) DESC, q.id LIMIT #{limit}

SELECT COUNT(ar.id) AS answers,
       COUNT(DISTINCT ar.student_id) AS active_students
FROM student_course sc
JOIN answer_record ar
  ON ar.student_id = sc.student_id
 AND ar.course_id = sc.course_id
 AND ar.is_correct IS NOT NULL
WHERE sc.course_id = #{courseId}

  AND ar.answered_at >= #{from}
  AND ar.answered_at < #{to}
